CREATE OR REPLACE VIEW `tb_inventory` AS select `i`.`company_id` AS `company_id`,`i`.`product_id` AS `product_id`,`p`.`sku` AS `sku`,`p`.`name` AS `name`,`p`.`descriptions` AS `descriptions`,`i`.`qty` AS `qty`,`i`.`modify_date` AS `modify_date`,`i`.`sale_price` AS `sp`,`i`.`purchased_price` AS `pp`,`p`.`sale_price` AS `sale_price`,`p`.`purchase_price` AS `purchase_price`,`p`.`category_id` AS `category_id` from (`inventory` `i` join `products` `p` on(`p`.`company_id` = `i`.`company_id` and `p`.`product_id` = `i`.`product_id`)) order by `i`.`company_id`,`p`.`sku`;
